(function(){'use strict';const docEl=document.documentElement;let SITE={};try{SITE=JSON.parse((document.getElementById('site-data')||{}).textContent||'{}');}catch(e){SITE={};}
const ROOT=()=>docEl.getAttribute('data-root')||'';const sources=(key,local)=>[(SITE.cdn||{})[key],ROOT()+'app/vendor/'+local].filter(Boolean).map((base)=>String(base).replace(/\/+$/,''));const loadScript=(src,id)=>new Promise((resolve,reject)=>{if(id&&document.getElementById(id))return resolve();const node=document.createElement('script');if(id)node.id=id;node.src=src;node.async=true;node.onload=()=>resolve();node.onerror=()=>{node.remove();reject(new Error('load failed: '+src));};document.head.appendChild(node);});const loadStyle=(href,id)=>{if(id&&document.getElementById(id))return;const node=document.createElement('link');if(id)node.id=id;node.rel='stylesheet';node.href=href;node.onerror=()=>node.remove();document.head.appendChild(node);};async function loadFrom(bases,file,id){let lastError=new Error('no source');for(const base of bases){try{await loadScript(base+'/'+file,id);return base;}catch(error){lastError=error;}}
throw lastError;}
const copyText=async(text)=>{try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true;}
const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');document.body.removeChild(area);return ok;}catch(e){return false;}};function initCode(scope){(scope||document).querySelectorAll('.codeblock').forEach((block)=>{const btn=block.querySelector('[data-copy]');const code=block.querySelector('code');if(btn&&code&&!btn.dataset.bound){btn.dataset.bound='1';btn.addEventListener('click',async()=>{const ok=await copyText(code.textContent);btn.classList.toggle('is-done',ok);const original=btn.textContent;btn.textContent=ok?'已复制':'复制失败';setTimeout(()=>{btn.textContent=original;btn.classList.remove('is-done');},1600);});}
const bar=block.querySelector('.codeblock__bar');if(block.classList.contains('codeblock--collapsible')&&bar&&!bar.dataset.bound){bar.dataset.bound='1';bar.addEventListener('click',(event)=>{if(event.target.closest('[data-copy]'))return;const collapsed=block.getAttribute('data-collapsed')==='true';block.setAttribute('data-collapsed',String(!collapsed));});}});}
function initLightbox(){let box=null;const ensure=()=>{if(box)return box;box=document.createElement('div');box.className='lightbox';box.hidden=true;box.innerHTML='<button type="button" class="lightbox__close" aria-label="关闭">'+'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button>'+'<div><img alt=""><p class="lightbox__caption"></p></div>';box.addEventListener('click',()=>{box.hidden=true;document.body.style.overflow='';});document.body.appendChild(box);return box;};document.addEventListener('click',(event)=>{const img=event.target.closest('.ink-prose img.post-image');if(!img)return;event.preventDefault();const node=ensure();node.querySelector('img').src=img.currentSrc||img.src;node.querySelector('.lightbox__caption').textContent=img.alt||'';node.hidden=false;document.body.style.overflow='hidden';});}
function stepTitle(step,index){const node=step.querySelector('.cot__step-title');return(node?node.textContent:step.getAttribute('data-title')||('步骤 '+(index+1))).trim();}
function initCot(scope){(scope||document).querySelectorAll('[data-cot]').forEach((cot)=>{if(cot.dataset.bound)return;cot.dataset.bound='1';const toggle=cot.querySelector('.cot__toggle');const panel=cot.querySelector('.cot__panel');if(panel)panel.style.maxHeight=panel.scrollHeight+'px';if(toggle){toggle.addEventListener('click',()=>{const collapsed=cot.classList.toggle('is-collapsed');toggle.setAttribute('aria-expanded',String(!collapsed));if(panel){panel.style.maxHeight=collapsed?'0px':panel.scrollHeight+'px';}});}
const copyBtn=cot.querySelector('[data-cot-copy]');if(copyBtn){copyBtn.addEventListener('click',async()=>{const title=(cot.querySelector('.cot__title')||{}).textContent||'';const steps=[...cot.querySelectorAll('.cot__step')].map((step,i)=>{const heading=stepTitle(step,i);const body=(step.querySelector('.cot__step-content')||{}).innerText||'';return(step.getAttribute('data-step')||i+1)+'. '+heading+'\n'+body.trim();}).join('\n\n');const ok=await copyText('## '+title+'\n\n'+steps);copyBtn.textContent=ok?'已复制':'失败';setTimeout(()=>{copyBtn.textContent='复制';},1500);});}
const exportBtn=cot.querySelector('[data-cot-export]');if(exportBtn){exportBtn.addEventListener('click',()=>{const title=(cot.querySelector('.cot__title')||{}).textContent||'cot';const steps=[...cot.querySelectorAll('.cot__step')].map((step,i)=>{const body=(step.querySelector('.cot__step-content')||{}).innerText||'';return'### '+stepTitle(step,i)+'\n\n'+body.trim();}).join('\n\n');const blob=new Blob(['# '+title+'\n\n'+steps+'\n'],{type:'text/markdown;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=title.replace(/[\\/:*?"<>|]/g,'_')+'.md';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),3000);});}
const hideBtn=cot.querySelector('[data-cot-hide]');if(hideBtn){hideBtn.addEventListener('click',()=>{const hidden=cot.classList.toggle('is-hidden');hideBtn.textContent=hidden?'显示':'隐藏';});}
const mindBtn=cot.querySelector('[data-cot-mindmap]');if(mindBtn){mindBtn.addEventListener('click',()=>{const existing=cot.querySelector('.cot__mindmap');if(existing){existing.remove();mindBtn.textContent='导图';return;}
const host=document.createElement('div');host.className='cot__mindmap';host.innerHTML=buildMindmap(cot);cot.querySelector('.cot__panel').appendChild(host);mindBtn.textContent='收起导图';});}});}
function buildMindmap(cot){const title=(cot.querySelector('.cot__title')||{}).textContent||'CoT';const steps=[...cot.querySelectorAll('.cot__step')].map((step,i)=>stepTitle(step,i));const w=720;const h=Math.max(320,steps.length*64+80);const cx=150;const cy=h/2;const right=340;const gap=steps.length>1?(h-96)/(steps.length-1):0;const nodes=steps.map((text,index)=>{const y=48+index*gap;return'<path class="mindmap__link" d="M'+cx+' '+cy+' C'+(cx+90)+' '+cy+', '+(right-120)+' '+y+', '+right+' '+y+'"/>'+'<circle class="mindmap__node" cx="'+right+'" cy="'+y+'" r="4"/>'+'<text class="mindmap__node-text" x="'+(right+12)+'" y="'+(y+4)+'">'+
escapeXml(text.slice(0,26))+'</text>';}).join('');return'<svg class="mindmap" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="思维导图">'+'<circle class="mindmap__node" cx="'+cx+'" cy="'+cy+'" r="52"/>'+'<text class="mindmap__node-text" x="'+cx+'" y="'+cy+'" text-anchor="middle" dominant-baseline="middle">'+
escapeXml(title.slice(0,8))+'</text>'+nodes+'</svg>';}
const escapeXml=(text)=>String(text).replace(/[<>&"']/g,(ch)=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'})[ch]);async function initMath(scope){const nodes=[...(scope||document).querySelectorAll('.math[data-tex]:not([data-rendered])')];if(!nodes.length)return;nodes.forEach((node)=>node.setAttribute('data-rendered','1'));try{const base=await loadFrom(sources('katex','katex'),'katex.min.js','ink-katex-js');loadStyle(base+'/katex.min.css','ink-katex-css');nodes.forEach((node)=>{const tex=node.getAttribute('data-tex')||'';const display=node.classList.contains('math--block');try{window.katex.render(tex,node,{displayMode:display,throwOnError:false,strict:false,trust:false});}catch(e){node.textContent=tex;}});}catch(e){nodes.forEach((node)=>{node.classList.add('math-error');node.textContent=node.getAttribute('data-tex')||node.textContent;});document.documentElement.setAttribute('data-math-fallback','1');}}
async function initMermaid(scope){const nodes=[...(scope||document).querySelectorAll('.mermaid:not([data-rendered])')];if(!nodes.length)return;nodes.forEach((node)=>node.setAttribute('data-rendered','1'));try{await loadFrom(sources('mermaid','mermaid'),'mermaid.min.js','ink-mermaid-js');const dark=document.documentElement.getAttribute('data-mode')==='dark';window.mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:dark?'dark':'neutral',fontFamily:'inherit',themeVariables:dark?{primaryColor:'#141416',primaryTextColor:'#eeeff1',lineColor:'#b9bfc8'}:{primaryColor:'#ffffff',primaryTextColor:'#101013',lineColor:'#8d939d'}});nodes.forEach((node,index)=>{const source=node.textContent.trim();const id='mmd-'+Date.now()+'-'+index;window.mermaid.render(id,source).then((result)=>{node.innerHTML=result.svg;}).catch(()=>{node.innerHTML='<pre class="mermaid-fallback">'+escapeXml(source)+'</pre>';});});}catch(e){nodes.forEach((node)=>{node.innerHTML='<pre class="mermaid-fallback">'+escapeXml(node.textContent.trim())+'</pre>';});document.documentElement.setAttribute('data-mermaid-fallback','1');}}
let commentsObserver=null;document.addEventListener('ink:mode',()=>{const iframe=document.querySelector('[data-comments] iframe.giscus-frame');if(!iframe)return;const mode=document.documentElement.getAttribute('data-mode')==='dark'?'dark':'light';iframe.contentWindow.postMessage({giscus:{setConfig:{theme:mode==='dark'?'dark_dimmed':'light'}}},'https://giscus.app');});function initComments(scope){if(commentsObserver){commentsObserver.disconnect();commentsObserver=null;}
const host=(scope||document).querySelector('[data-comments]');if(!host)return;const render=()=>{if(host.dataset.loaded)return;host.dataset.loaded='1';const mode=document.documentElement.getAttribute('data-mode')==='dark'?'dark':'light';if(host.dataset.repo){const frame=document.createElement('script');frame.src='https://giscus.app/client.js';frame.async=true;frame.crossOrigin='anonymous';const map={'data-repo':host.dataset.repo,'data-repo-id':host.dataset.repoId,'data-category':host.dataset.category,'data-category-id':host.dataset.categoryId,'data-mapping':host.dataset.mapping||'pathname','data-strict':host.dataset.strict||'0','data-reactions-enabled':host.dataset.reactions||'1','data-emit-metadata':host.dataset.emitMetadata||'0','data-input-position':host.dataset.inputPosition||'top','data-theme':mode==='dark'?'dark_dimmed':'light','data-lang':host.dataset.lang||'zh-CN','data-loading':'lazy'};Object.keys(map).forEach((key)=>{if(map[key])frame.setAttribute(key,map[key]);});host.appendChild(frame);const observer=new MutationObserver(()=>{const iframe=host.querySelector('iframe.giscus-frame');if(!iframe)return;iframe.contentWindow.postMessage({giscus:{setConfig:{theme:mode==='dark'?'dark_dimmed':'light'}}},'https://giscus.app');});observer.observe(host,{childList:true,subtree:true});}else if(host.dataset.utterancesRepo){const frame=document.createElement('script');frame.src='https://utteranc.es/client.js';frame.async=true;frame.crossOrigin='anonymous';frame.setAttribute('repo',host.dataset.utterancesRepo);frame.setAttribute('issue-term',host.dataset.issueTerm||'pathname');frame.setAttribute('label',host.dataset.label||'comment');frame.setAttribute('theme',mode==='dark'?'github-dark':'github-light');host.appendChild(frame);}else if(host.dataset.disqusShortname){window.disqus_config=function(){this.page.url=location.href;this.page.identifier=location.pathname;};const frame=document.createElement('script');frame.src='https://'+host.dataset.disqusShortname+'.disqus.com/embed.js';frame.setAttribute('data-timestamp',String(Date.now()));host.appendChild(frame);}};if('IntersectionObserver'in window){commentsObserver=new IntersectionObserver((entries)=>{if(entries.some((entry)=>entry.isIntersecting)){render();if(commentsObserver){commentsObserver.disconnect();commentsObserver=null;}}},{rootMargin:'240px'});commentsObserver.observe(host);}else{render();}}
const LIKE_KEY='ink-likes';function readLikes(){try{return JSON.parse(localStorage.getItem(LIKE_KEY)||'{}');}catch(e){return{};}}
function writeLikes(value){try{localStorage.setItem(LIKE_KEY,JSON.stringify(value));}catch(e){}}
function initActions(scope){scope=scope||document;const postNode=document.getElementById('post-data');let post=null;try{post=postNode?JSON.parse(postNode.textContent):null;}catch(e){post=null;}
let id=(post&&post.id)||'';if(!id){const holder=scope.querySelector('[data-post-id]')||document.querySelector('[data-post-id]');if(holder)id=holder.getAttribute('data-post-id')||'';}
scope.querySelectorAll('[data-action="like"]').forEach((btn)=>{if(btn.dataset.bound)return;btn.dataset.bound='1';if(!id){btn.hidden=true;return;}
const likes=readLikes();const label=btn.querySelector('[data-like-label]');const sync=()=>{const on=Boolean(likes[id]);btn.setAttribute('aria-pressed',String(on));btn.classList.toggle('is-liked',on);if(label)label.textContent=on?'已喜欢':(SITE.i18n&&SITE.i18n['label.like'])||'喜欢';};sync();btn.addEventListener('click',()=>{if(likes[id])delete likes[id];else likes[id]=Date.now();writeLikes(likes);sync();});});scope.querySelectorAll('[data-action="copy-link"]').forEach((btn)=>{if(btn.dataset.bound)return;btn.dataset.bound='1';btn.addEventListener('click',async()=>{const ok=await copyText(location.href);const original=btn.textContent;btn.textContent=ok?'已复制':'复制失败';setTimeout(()=>{btn.textContent=original;},1500);});});scope.querySelectorAll('[data-action="share"]').forEach((btn)=>{if(btn.dataset.bound)return;btn.dataset.bound='1';btn.addEventListener('click',async()=>{const shareData={title:(post&&post.title)||document.title,url:location.href};if(navigator.share){try{await navigator.share(shareData);return;}catch(e){}}
const ok=await copyText(location.href);const original=btn.textContent;btn.textContent=ok?'链接已复制':'分享失败';setTimeout(()=>{btn.textContent=original;},1500);});});scope.querySelectorAll('[data-action="print"]').forEach((btn)=>{if(btn.dataset.bound)return;btn.dataset.bound='1';btn.addEventListener('click',()=>window.print());});}
function initImages(scope){(scope||document).querySelectorAll('img').forEach((img)=>{if(img.dataset.bound)return;img.dataset.bound='1';img.addEventListener('error',()=>{img.style.minHeight='60px';img.style.background='repeating-linear-gradient(45deg, var(--line-2) 0 8px, transparent 8px 16px)';img.setAttribute('data-broken','1');});});}
function enhanceAll(scope){initCode(scope);initCot(scope);initImages(scope);}
document.addEventListener('DOMContentLoaded',()=>{enhanceAll(document);initLightbox();initActions(document);initComments(document);initMath(document);initMermaid(document);});document.addEventListener('ink:view',()=>{enhanceAll(document.getElementById('view-dynamic')||document);});document.addEventListener('ink:navigate',(event)=>{const scope=(event.detail&&event.detail.main)||document;enhanceAll(scope);initActions(scope);initComments(scope);initMath(scope);initMermaid(scope);});window.InkEnhance={init:enhanceAll,copy:copyText,setSiteData(json){SITE=json||SITE;},};})();